selector_to_html = {"a[href=\"#gpu-cluster-validation-slurm\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">GPU Cluster Validation (Slurm)<a class=\"headerlink\" href=\"#gpu-cluster-validation-slurm\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#quick-acceptance-checklist\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Quick Acceptance Checklist<a class=\"headerlink\" href=\"#quick-acceptance-checklist\" title=\"Link to this heading\">#</a></h2><p>To verify acceptance readiness, run the following commands in order:</p>", "a[href=\"#flagtensor-standard-acceptance-commands\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">FlagTensor Standard Acceptance Commands<a class=\"headerlink\" href=\"#flagtensor-standard-acceptance-commands\" title=\"Link to this heading\">#</a></h1><p>This document provides the standard commands for running FlagTensor acceptance checks.</p>", "a[href=\"#static-quality-checks\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Static Quality Checks<a class=\"headerlink\" href=\"#static-quality-checks\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#correctness-via-pytest-category-files-primary\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Correctness via Pytest \u2014 Category Files (Primary)<a class=\"headerlink\" href=\"#correctness-via-pytest-category-files-primary\" title=\"Link to this heading\">#</a></h3><p>Category-level correctness files are the formal acceptance interface:</p>", "a[href=\"#performance-testing\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Performance Testing<a class=\"headerlink\" href=\"#performance-testing\" title=\"Link to this heading\">#</a></h2><h3>Smoke Performance (CI-level)<a class=\"headerlink\" href=\"#smoke-performance-ci-level\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#performance-via-category-benchmarks-primary\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Performance via Category Benchmarks (Primary)<a class=\"headerlink\" href=\"#performance-via-category-benchmarks-primary\" title=\"Link to this heading\">#</a></h3><p>Category-level benchmark files are the formal acceptance interface. Individual operators are selected via <code class=\"docutils literal notranslate\"><span class=\"pre\">pytest</span> <span class=\"pre\">-m</span> <span class=\"pre\">&lt;op&gt;</span></code> markers:</p>", "a[href=\"#smoke-correctness-ci-level\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Smoke Correctness (CI-level)<a class=\"headerlink\" href=\"#smoke-correctness-ci-level\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#prerequisites\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Prerequisites<a class=\"headerlink\" href=\"#prerequisites\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#acceptance-correctness-full-coverage\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Acceptance Correctness (Full Coverage)<a class=\"headerlink\" href=\"#acceptance-correctness-full-coverage\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#smoke-performance-ci-level\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Smoke Performance (CI-level)<a class=\"headerlink\" href=\"#smoke-performance-ci-level\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#acceptance-performance-full-coverage\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Acceptance Performance (Full Coverage)<a class=\"headerlink\" href=\"#acceptance-performance-full-coverage\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#environment-export\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Environment Export<a class=\"headerlink\" href=\"#environment-export\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#performance-via-single-operator-legacy-debug\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Performance via Single Operator \u2014 Legacy/Debug<a class=\"headerlink\" href=\"#performance-via-single-operator-legacy-debug\" title=\"Link to this heading\">#</a></h3><p>Legacy per-operator benchmark files are retained for debugging but are not part of the acceptance interface:</p>", "a[href=\"#weekly-regression\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Weekly Regression<a class=\"headerlink\" href=\"#weekly-regression\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#correctness-testing\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Correctness Testing<a class=\"headerlink\" href=\"#correctness-testing\" title=\"Link to this heading\">#</a></h2><h3>Smoke Correctness (CI-level)<a class=\"headerlink\" href=\"#smoke-correctness-ci-level\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#report-generation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Report Generation<a class=\"headerlink\" href=\"#report-generation\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#registry-operations\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Registry Operations<a class=\"headerlink\" href=\"#registry-operations\" title=\"Link to this heading\">#</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
